ALTER TABLE public.approvals ADD COLUMN area text, ADD COLUMN decided_by uuid, ADD COLUMN decided_at timestamptz;
DROP POLICY "gestao all" ON public.approvals;
CREATE POLICY "approval authorized reads" ON public.approvals FOR SELECT TO authenticated USING(public.is_partner(auth.uid()) OR (public.access_level_for(auth.uid())='gerentes' AND level<>'socios') OR (level='diretor' AND public.access_level_for(auth.uid()) IN ('rh','financas','marketing') AND area=(SELECT a.area FROM public.user_access a WHERE a.user_id=auth.uid())));
CREATE FUNCTION public.decide_approval(_id uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.approvals; BEGIN SELECT * INTO a FROM public.approvals WHERE id=_id FOR UPDATE; IF NOT(public.is_partner(auth.uid()) OR (public.access_level_for(auth.uid())='gerentes' AND a.level<>'socios') OR (a.level='diretor' AND public.access_level_for(auth.uid()) IN ('rh','financas','marketing') AND a.area=(SELECT area FROM public.user_access WHERE user_id=auth.uid()))) THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF a.status<>'pendente' OR _status NOT IN ('aprovado','rejeitado') THEN RAISE EXCEPTION 'Estado inválido'; END IF; UPDATE public.approvals SET status=_status,decided_by=auth.uid(),decided_at=now() WHERE id=_id; INSERT INTO public.audit_events(actor_id,action,target_id,details) VALUES(auth.uid(),'decisao_pedido',_id,jsonb_build_object('status',_status)); END $$;
REVOKE ALL ON FUNCTION public.decide_approval(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.decide_approval(uuid,text) TO authenticated;
CREATE FUNCTION public.enforce_pending_approval() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status<>'pendente' OR NEW.amount<0 OR NEW.level NOT IN ('diretor','gerente','socios') OR NEW.decided_by IS NOT NULL THEN RAISE EXCEPTION 'Pedido inválido'; END IF; RETURN NEW; END $$;
CREATE TRIGGER pending_approval BEFORE INSERT ON public.approvals FOR EACH ROW EXECUTE FUNCTION public.enforce_pending_approval();
CREATE FUNCTION public.sync_project_totals(_updates jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p jsonb; BEGIN IF NOT public.is_partner(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; FOR p IN SELECT * FROM jsonb_array_elements(_updates) LOOP UPDATE public.projects SET revenue=(p->>'revenue')::numeric,expenses=(p->>'expenses')::numeric WHERE id=(p->>'id')::uuid; IF NOT FOUND THEN RAISE EXCEPTION 'Projeto inexistente'; END IF; END LOOP; UPDATE public.workspace_config SET last_synced_at=now() WHERE id=1; END $$;
REVOKE ALL ON FUNCTION public.sync_project_totals(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.sync_project_totals(jsonb) TO authenticated;